/* Original vector equipment illustrations. No state or gameplay decisions live here. */
const ink='#193e4b',light='#e7f2f0',teal='#4a9b94',aqua='#a7d7cc',edge='#b9cbd1';
export const ART_KINDS=Object.freeze(['desktop','laptop','tablet','server','wearable','switch4','switch8','access-point','ethernet-adapter','sensor-dock']);
function frame(body,kind){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 100" class="device-art" aria-hidden="true" focusable="false" data-art-kind="${kind}">${body}</svg>`;}
const screen=(x,y,w,h)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="5" fill="${ink}"/><rect x="${x+5}" y="${y+5}" width="${w-10}" height="${h-10}" rx="2" fill="${aqua}"/><path d="M${x+10} ${y+12}h${w/2}m-${w/2} 7h${w/3}" stroke="${teal}" stroke-width="3" opacity=".75"/>`;
function ports(n){let b='';for(let i=0;i<n;i++)b+=`<rect data-art-port="ethernet" data-art-port-index="${i+1}" x="${18+(i%4)*20}" y="${n===8?48+Math.floor(i/4)*13:53}" width="13" height="8" rx="1" fill="${ink}"/><path d="M${20+(i%4)*20} ${n===8?54+Math.floor(i/4)*13:59}h9" stroke="#e6be71" stroke-width="1.5"/>`;return b;}
export function deviceSvg(kind){
 kind=ART_KINDS.includes(kind)?kind:'unknown';
 let body='';
 if(kind==='desktop')body=`<ellipse cx="58" cy="86" rx="49" ry="8" fill="#0d30371a"/><path d="M23 31l45-12 24 8-46 13z" fill="${edge}"/>${screen(14,25,65,43)}<path d="M43 68v11m-15 3h33" stroke="${ink}" stroke-width="6"/><rect x="85" y="37" width="23" height="44" rx="4" fill="${teal}"/><path d="M90 47h13m-13 8h13" stroke="${ink}" stroke-width="3"/><rect data-art-port="ethernet" data-art-port-index="1" x="91" y="59" width="12" height="7" rx="1" fill="${ink}"/><path d="M93 64h8" stroke="#e6be71" stroke-width="1.5"/><circle cx="97" cy="71" r="3" fill="${light}"/><path d="M16 84h57l7 7H8z" fill="${edge}"/>`;
 else if(kind==='laptop')body=`<ellipse cx="61" cy="86" rx="48" ry="8" fill="#0d30371a"/>${screen(22,23,72,47)}<path d="M22 70h72l15 18H9z" fill="${edge}" stroke="${ink}" stroke-width="3" stroke-linejoin="round"/><path d="M29 75h58m-63 5h68" stroke="${ink}" stroke-width="2" opacity=".5"/><path d="M47 83h22" stroke="${teal}" stroke-width="4"/>`;
 else if(kind==='tablet')body=`<ellipse cx="61" cy="86" rx="35" ry="7" fill="#0d30371a"/><rect x="32" y="11" width="57" height="77" rx="8" fill="${ink}"/><rect x="37" y="18" width="47" height="60" rx="3" fill="${aqua}"/><path d="M45 29h27m-27 10h20m-20 10h27" stroke="${teal}" stroke-width="4"/><circle cx="61" cy="83" r="2.5" fill="${light}"/>`;
 else if(kind==='server')body=`<ellipse cx="61" cy="87" rx="35" ry="7" fill="#0d30371a"/><path d="M37 16l38-6 14 10-39 8z" fill="${edge}"/><path d="M76 21l13-1v61L76 88z" fill="${teal}"/><rect x="32" y="21" width="46" height="67" rx="5" fill="${ink}"/><rect data-art-port="ethernet" data-art-port-index="1" x="79" y="63" width="7" height="11" rx="1" fill="${ink}"/>${[32,48,64].map(y=>`<rect x="38" y="${y}" width="34" height="11" rx="2" fill="${edge}"/><path d="M42 ${y+5}h15" stroke="${ink}" stroke-width="2"/><circle cx="66" cy="${y+5}" r="2" fill="${teal}"/>`).join('')}`;
 else if(kind==='wearable')body=`<ellipse cx="61" cy="87" rx="30" ry="7" fill="#0d30371a"/><rect x="47" y="3" width="28" height="92" rx="10" fill="${teal}"/><rect x="32" y="23" width="58" height="53" rx="13" fill="${ink}"/><rect x="39" y="30" width="44" height="39" rx="6" fill="${aqua}"/><path d="M47 44h27m-27 8h18" stroke="${teal}" stroke-width="4"/><circle cx="61" cy="60" r="3" fill="${ink}"/>`;
 else if(kind==='switch4'||kind==='switch8')body=`<ellipse cx="60" cy="80" rx="49" ry="7" fill="#0d30371a"/><path d="M13 37l18-14h76L99 37z" fill="${light}" stroke="${ink}" stroke-width="2"/><rect x="12" y="37" width="88" height="38" rx="5" fill="${teal}" stroke="${ink}" stroke-width="2"/>${ports(kind==='switch8'?8:4)}`;
 else if(kind==='access-point')body=`<ellipse cx="60" cy="83" rx="40" ry="7" fill="#0d30371a"/><path d="M33 63L26 21m59 42 8-42" stroke="${ink}" stroke-width="5" stroke-linecap="round"/><path d="M26 62l23-13h45L78 64z" fill="${light}"/><rect x="25" y="62" width="69" height="20" rx="7" fill="${teal}" stroke="${ink}" stroke-width="2"/><rect data-art-port="ethernet" data-art-port-index="1" x="40" y="68" width="14" height="8" rx="1" fill="${ink}"/><path d="M51 33q10-9 20 0m-15 7q5-5 10 0" fill="none" stroke="${teal}" stroke-width="4" stroke-linecap="round"/><circle cx="61" cy="46" r="2" fill="${ink}"/>`;
 else if(kind==='ethernet-adapter')body=`<path d="M24 34c30-25 37 9 26 21" fill="none" stroke="${ink}" stroke-width="5"/><rect x="15" y="25" width="20" height="14" rx="2" fill="${edge}"/><path d="M48 53l30-9 18 14-29 10z" fill="${light}"/><rect x="44" y="56" width="40" height="27" rx="5" fill="${teal}"/><rect data-art-port="ethernet" data-art-port-index="1" x="55" y="64" width="19" height="12" fill="${ink}"/>`;
 else if(kind==='sensor-dock')body=`<path d="M29 61l30-18 35 18-31 18z" fill="${edge}"/><path d="M29 61v16l34 16 31-16V61L63 78z" fill="${teal}"/><rect x="49" y="32" width="25" height="34" rx="7" fill="${ink}"/><path d="M54 49h15m-15 6h15" stroke="${aqua}" stroke-width="3"/>`;
 else body=`<rect x="28" y="22" width="64" height="56" rx="9" fill="${edge}" stroke="${ink}" stroke-width="3"/>`;
 return frame(body,kind);
}
export const ART_VERSION='0.4.0';
